arguments.new_str:
class EnvVarCheck
{
    void CheckFlag()
    {
        // On Linux, set via: export MY_FLAG=""
        // .NET 9: empty env vars are no longer treated as unset —
        // GetEnvironmentVariable now returns "" instead of null.
        // Use a process-level check to distinguish "not set" from "explicitly empty".
        var val = Environment.GetEnvironmentVariable("MY_FLAG");
        if (!IsEnvironmentVariableSet("MY_FLAG"))
        {
            Console.WriteLine("MY_FLAG not set, using default");
        }
    }

    private static bool IsEnvironmentVariableSet(string variable)
    {
        return Environment.GetEnvironmentVariables().Contains(variable);
    }
}

