using System.IO.Compression;
using System.Text;
class ZipCreator
{
    void CreateArchive()
    {
        // .NET 9: ZipArchiveEntry now respects the UTF-8 flag in the entry header.
        // The legacy Java consumer expects Shift-JIS filenames, so we must use
        // the ZipArchive constructor that accepts a non-UTF-8 encoding and does
        // NOT set the UTF-8 flag on entries.
        Encoding.RegisterProvider(CodePagesEncodingProvider.Instance);
        var shiftJis = Encoding.GetEncoding("shift_jis");

        using var stream = new FileStream("data.zip", FileMode.Create);
        using var archive = new ZipArchive(stream, ZipArchiveMode.Create, leaveOpen: false, entryNameEncoding: shiftJis);
        archive.CreateEntry("レポート/月次.csv");  // Japanese path — encoded as Shift-JIS
        archive.CreateEntry("données/résumé.txt"); // French accented
    }
}

// .NET 9: [FromKeyedServices] no longer falls back to non-keyed registrations.
// Register as a keyed service to match the controller's [FromKeyedServices("cache")].
services.AddKeyedSingleton<ICache, RedisCache>("cache");

